import {
    COACHING_GOALS_KEY,
    COACHING_TONE_KEY,
    COACHING_WORKOUT_WINDOW_KEY,
    createSettingsRepository,
    parseWorkoutWindow,
    type DbDriver,
    type WorkoutWindow,
} from '@motivation/shared';
import { DbService } from '../db/db.service.js';
import { requestSync } from './sync/auto-sync.js';

/**
 * Story 074 — user-editable prompt context for the overnight coaching run.
 * Stored as separate `settings` rows (`coaching.goals`, `coaching.tone`, `coaching.workout_window`)
 * so each can be cleared independently. The keys, the window and its default are shared with the
 * server (story 390); the local writes propagate via the standard settings sync.
 */

export interface CoachingPreferences {
    goals: string;
    tone: string;
    /** Workout-eligible window the coach uses for free-slot suggestions (story 153). */
    workoutWindow: WorkoutWindow;
}

export interface CoachingPreferencesServiceDeps {
    driver?: () => Promise<DbDriver>;
}

async function defaultDriver(): Promise<DbDriver> {
    const service = DbService.getInstance();
    await service.init();
    return service.driver;
}

export class CoachingPreferencesService {
    private readonly driverFn: () => Promise<DbDriver>;

    constructor(deps: CoachingPreferencesServiceDeps = {}) {
        this.driverFn = deps.driver ?? defaultDriver;
    }

    async get(): Promise<CoachingPreferences> {
        const settings = createSettingsRepository(await this.driverFn());
        const rows = await settings.getMany([COACHING_GOALS_KEY, COACHING_TONE_KEY, COACHING_WORKOUT_WINDOW_KEY]);
        return {
            goals: rows[COACHING_GOALS_KEY] ?? '',
            tone: rows[COACHING_TONE_KEY] ?? '',
            workoutWindow: parseWorkoutWindow(rows[COACHING_WORKOUT_WINDOW_KEY]),
        };
    }

    async set(partial: Partial<CoachingPreferences>): Promise<void> {
        const settings = createSettingsRepository(await this.driverFn());
        if (partial.goals !== undefined) await settings.set(COACHING_GOALS_KEY, partial.goals);
        if (partial.tone !== undefined) await settings.set(COACHING_TONE_KEY, partial.tone);
        if (partial.workoutWindow !== undefined) {
            await settings.set(COACHING_WORKOUT_WINDOW_KEY, JSON.stringify(partial.workoutWindow));
        }
        requestSync('settings');
    }
}

export const coachingPreferencesService = new CoachingPreferencesService();
